  f.company.createTask('human',scout,{...objective,objective:'Ordinary visible analysis'},null,'research');const ordinary=f.company.claimNext()!;
  const old={worker_id:scout.worker_id,runtime_type:'fake',runtime_reference:'ordinary-reference',workspace_path:scout.workspace_path,created_at:new Date().toISOString()};
