  let release!:()=>void;f.company.research.provider={name:'controlled-gated-source',async search(_q,_s,h){h.invoking();await new Promise<void>(r=>release=r);h.settled();return {provider:'controlled',outcome:'succeeded',summary:'Controlled response',sources:[{url:'https://example.com/documentation',title:'Controlled source',content:'LATE_SOURCE_SENTINEL',kind:'search_snippet',retrieved_at:new Date().toISOString(),observed_at:null,published_at:null,freshness:'unknown',omissions:'Controlled fixture'}]};}};
  const pending=f.company.research.callTool(task.context,'search','research_search',{query:'public software documentation'},new AbortController().signal) as Promise<{ok:boolean}>;await Promise.resolve();if(action==='revoke')f.company.research.revoke({grant_id:grant.grant_id});else if(action==='pause')f.company.mandates.control({mandate_id:f.m.mandate_id,action:'pause'});else{f.advance(1);f.company.mandates.withdrawObservation({observation_id:o.observation_id});}release();assert.equal((await pending).ok,false);assert.equal(f.store.get<{n:number}>('SELECT count(*) n FROM research_sources')!.n,0);// Grant revocation aborts pending I/O; mandate scope changes reject the settled callback. Both retain a failed, consumed operation without sources.
