  const linked=f.company.mandates.callTool(coordinator.context,'assign','assign_internal_task',{decision_id:d.decision_id,worker_id:scout.worker_id,objective:'Bounded internal analysis',acceptance_criteria:'Report',constraints:'Internal only'}) as {task_id:string};
