  const task=f.company.mandates.callTool(c.context,'assign','assign_internal_task',{decision_id:d.decision_id,worker_id:scout.worker_id,objective:'Private internal analysis',acceptance_criteria:'Report',constraints:'Internal only'}) as {task_id:string};f.company.mandates.callTool(c.context,'wait','wait_for_internal_work',{summary:'Await result'});f.company.finish(c.execution.execution_id,{status:'completed',settled:true,summary:'Waiting'});
  const x=f.company.claimNext()!,session=f.company.mandates.taskSession(x.context,companyTools(scout))!;f.company.recordRuntimeEvent(x.context,'runtime_turn_starting',{context_chars:100});f.company.finish(x.execution.execution_id,{status:outcome,settled:outcome==='failed',error:'Controlled provider outcome'});
